static int sis630_transaction_wait ( struct i2c_adapter * adap , int size ) { int temp , result = 0 , timeout = 0 ; { msleep ( 1 ) ; temp = sis630_read ( SMB_STS ) ; } ! ( temp & 0x0e ) && ( timeout ++ < MAX_TIMEOUT ) ; if ( timeout > MAX_TIMEOUT ) { dev_dbg ( & adap -> dev , "SMBus Timeout!\n" ) ; result = - ETIMEDOUT ; } if ( temp & SMBERR_STS ) { dev_dbg ( & adap -> dev , "Error: Failed bus transaction\n" ) ; result = - ENXIO ; } if ( temp & SMBCOL_STS ) { dev_err ( & adap -> dev , "Bus collision!\n" ) ; result = - EAGAIN ; } return result ; } 